HTML_CONTENT = '<!DOCTYPE html>\n<html lang="zh-CN" class="dark">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>OmniMedia Pro · 云端服务后台管理系统</title>\n    <!-- TailwindCSS & Chart.js & Lucide Icons -->\n    <script src="https://cdn.tailwindcss.com"></script>\n    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>\n    <script src="https://unpkg.com/lucide@latest"></script>\n    <style>\n        body {\n            background-color: #0b0f19;\n            color: #e2e8f0;\n            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", "PingFang SC", "Microsoft YaHei", sans-serif;\n        }\n        .admin-glass {\n            background: rgba(17, 24, 39, 0.75);\n            backdrop-filter: blur(16px);\n            border: 1px solid rgba(255, 255, 255, 0.08);\n        }\n        .admin-card {\n            background: linear-gradient(145deg, rgba(30, 41, 59, 0.7) 0%, rgba(15, 23, 42, 0.8) 100%);\n            border: 1px solid rgba(255, 255, 255, 0.08);\n            box-shadow: 0 10px 30px -10px rgba(0, 0, 0, 0.5);\n        }\n        .glow-indigo {\n            box-shadow: 0 0 25px rgba(99, 102, 241, 0.2);\n        }\n        .glow-green {\n            box-shadow: 0 0 15px rgba(16, 185, 129, 0.3);\n        }\n    </style>\n</head>\n<body class="min-h-screen flex flex-col">\n\n    <!-- 顶部导航栏 -->\n    <header class="w-full admin-glass border-b border-slate-800 sticky top-0 z-50 px-6 py-4 flex items-center justify-between">\n        <div class="flex items-center space-x-3">\n            <div class="w-10 h-10 rounded-xl bg-gradient-to-tr from-indigo-600 to-cyan-400 flex items-center justify-center shadow-md">\n                <i data-lucide="shield-check" class="w-5 h-5 text-white"></i>\n            </div>\n            <div>\n                <div class="flex items-center space-x-2">\n                    <h1 class="text-base font-bold text-white tracking-wide">OmniMedia Cloud</h1>\n                    <span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-indigo-500/20 text-indigo-300 border border-indigo-500/30">ADMIN V2.5</span>\n                </div>\n                <p class="text-xs text-slate-400">短视频与实况图解析核心 · 后台管理控制台</p>\n            </div>\n        </div>\n\n        <div class="flex items-center space-x-4">\n            <div class="hidden sm:flex items-center space-x-2 px-3 py-1.5 rounded-full bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 text-xs font-medium">\n                <span class="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span>\n                <span>云端服务正常运行 (Vercel Global)</span>\n            </div>\n            <button onclick="refreshData()" class="px-3.5 py-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs font-semibold flex items-center space-x-1.5 transition border border-slate-700">\n                <i data-lucide="refresh-cw" class="w-3.5 h-3.5"></i>\n                <span>刷新监控</span>\n            </button>\n        </div>\n    </header>\n\n    <!-- 主体监控大屏 -->\n    <main class="flex-1 max-w-7xl w-full mx-auto p-6 space-y-6">\n\n        <!-- 4 大核心指标卡片 -->\n        <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">\n            <div class="admin-card rounded-2xl p-5 space-y-2">\n                <div class="flex items-center justify-between text-slate-400">\n                    <span class="text-xs font-medium">累计云端解析量</span>\n                    <i data-lucide="zap" class="w-4 h-4 text-indigo-400"></i>\n                </div>\n                <div class="flex items-baseline space-x-2">\n                    <span id="metric-total" class="text-2xl font-black text-white">1,842</span>\n                    <span class="text-xs text-emerald-400 font-bold">+18.5% 今日</span>\n                </div>\n                <p class="text-[11px] text-slate-500">包含 4K 视频、实况图与图集请求</p>\n            </div>\n\n            <div class="admin-card rounded-2xl p-5 space-y-2">\n                <div class="flex items-center justify-between text-slate-400">\n                    <span class="text-xs font-medium">接口平均响应耗时</span>\n                    <i data-lucide="gauge" class="w-4 h-4 text-cyan-400"></i>\n                </div>\n                <div class="flex items-baseline space-x-2">\n                    <span id="metric-latency" class="text-2xl font-black text-white">186</span>\n                    <span class="text-xs text-slate-400">ms</span>\n                    <span class="text-xs text-emerald-400 font-bold">极速</span>\n                </div>\n                <p class="text-[11px] text-slate-500">Vercel Serverless 国内智能路由</p>\n            </div>\n\n            <div class="admin-card rounded-2xl p-5 space-y-2">\n                <div class="flex items-center justify-between text-slate-400">\n                    <span class="text-xs font-medium">解析成功率</span>\n                    <i data-lucide="activity" class="w-4 h-4 text-emerald-400"></i>\n                </div>\n                <div class="flex items-baseline space-x-2">\n                    <span id="metric-rate" class="text-2xl font-black text-white">99.8</span>\n                    <span class="text-xs text-slate-400">%</span>\n                    <span class="text-xs text-emerald-400 font-bold">高稳定</span>\n                </div>\n                <p class="text-[11px] text-slate-500">防盗链穿透与自动容灾生效中</p>\n            </div>\n\n            <div class="admin-card rounded-2xl p-5 space-y-2">\n                <div class="flex items-center justify-between text-slate-400">\n                    <span class="text-xs font-medium">已连接手机终端</span>\n                    <i data-lucide="smartphone" class="w-4 h-4 text-amber-400"></i>\n                </div>\n                <div class="flex items-baseline space-x-2">\n                    <span class="text-2xl font-black text-white">Redmi</span>\n                    <span class="text-xs px-2 py-0.5 rounded-full bg-emerald-500/20 text-emerald-300 font-bold">已连接</span>\n                </div>\n                <p class="text-[11px] text-slate-500">Android 14 · OmniMedia Pro App</p>\n            </div>\n        </div>\n\n        <!-- 图表监控区 (2 列) -->\n        <div class="grid grid-cols-1 lg:grid-cols-3 gap-6">\n            <!-- 左侧：解析流量趋势图 -->\n            <div class="lg:col-span-2 admin-card rounded-2xl p-5 space-y-4">\n                <div class="flex items-center justify-between border-b border-slate-800 pb-3">\n                    <div class="flex items-center space-x-2">\n                        <i data-lucide="line-chart" class="w-4 h-4 text-indigo-400"></i>\n                        <h2 class="text-sm font-bold text-white">过去 7 天解析流量趋势</h2>\n                    </div>\n                    <span class="text-xs text-slate-400">单位：次 / 日</span>\n                </div>\n                <div class="h-64 w-full">\n                    <canvas id="trafficChart"></canvas>\n                </div>\n            </div>\n\n            <!-- 右侧：平台与格式占比 -->\n            <div class="admin-card rounded-2xl p-5 space-y-4">\n                <div class="flex items-center justify-between border-b border-slate-800 pb-3">\n                    <div class="flex items-center space-x-2">\n                        <i data-lucide="pie-chart" class="w-4 h-4 text-cyan-400"></i>\n                        <h2 class="text-sm font-bold text-white">平台与媒体格式分布</h2>\n                    </div>\n                </div>\n                <div class="h-64 w-full flex items-center justify-center">\n                    <canvas id="distributionChart"></canvas>\n                </div>\n            </div>\n        </div>\n\n        <!-- 在线测试调试沙盒 (Admin API Sandbox) -->\n        <div class="admin-card rounded-2xl p-5 space-y-4">\n            <div class="flex items-center justify-between border-b border-slate-800 pb-3">\n                <div class="flex items-center space-x-2">\n                    <i data-lucide="terminal" class="w-4 h-4 text-indigo-400"></i>\n                    <h2 class="text-sm font-bold text-white">云端接口在线测试沙盒 (API Debugger)</h2>\n                </div>\n                <span class="text-xs text-slate-400">实时测试抖音/快手直链提取</span>\n            </div>\n\n            <div class="flex flex-col sm:flex-row items-center gap-3">\n                <input id="test-url" type="text" placeholder="输入抖音 / 快手分享链接进行后台调试..." \n                    class="flex-1 bg-slate-900/90 border border-slate-700 rounded-xl px-4 py-2.5 text-xs text-white placeholder-slate-500 focus:outline-none focus:border-indigo-500">\n                <button onclick="runApiTest()" class="w-full sm:w-auto px-5 py-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold flex items-center justify-center space-x-1.5 transition">\n                    <i data-lucide="play" class="w-3.5 h-3.5"></i>\n                    <span>发送测试请求</span>\n                </button>\n            </div>\n\n            <!-- 调试输出窗口 -->\n            <div id="test-output-box" class="bg-slate-950 rounded-xl p-4 border border-slate-800 text-[11px] font-mono text-slate-300 hidden max-h-52 overflow-y-auto">\n                <pre id="test-output-json"></pre>\n            </div>\n        </div>\n\n        <!-- 实时请求日志流 -->\n        <div class="admin-card rounded-2xl p-5 space-y-4">\n            <div class="flex items-center justify-between border-b border-slate-800 pb-3">\n                <div class="flex items-center space-x-2">\n                    <i data-lucide="list" class="w-4 h-4 text-emerald-400"></i>\n                    <h2 class="text-sm font-bold text-white">实时服务请求日志 (Live Request Logs)</h2>\n                </div>\n                <span class="text-xs text-slate-400">自动实时刷新</span>\n            </div>\n\n            <div class="overflow-x-auto">\n                <table class="w-full text-left text-xs">\n                    <thead>\n                        <tr class="text-slate-400 border-b border-slate-800 pb-2">\n                            <th class="py-2.5 px-3">请求时间</th>\n                            <th class="py-2.5 px-3">来源平台</th>\n                            <th class="py-2.5 px-3">媒体类型</th>\n                            <th class="py-2.5 px-3">耗时</th>\n                            <th class="py-2.5 px-3">终端设备</th>\n                            <th class="py-2.5 px-3">状态</th>\n                        </tr>\n                    </thead>\n                    <tbody id="logs-tbody" class="divide-y divide-slate-800/60 font-mono text-slate-300">\n                        <!-- 动态生成的日志行 -->\n                    </tbody>\n                </table>\n            </div>\n        </div>\n\n    </main>\n\n    <!-- 底部状态 -->\n    <footer class="w-full py-4 text-center text-xs text-slate-500 border-t border-slate-800/80 mt-auto">\n        OmniMedia Pro Cloud Backend · Powered by FastAPI & Vercel Edge Runtime · 24/7 Dedicated Server\n    </footer>\n\n    <script>\n        // 初始化图标与图表\n        document.addEventListener("DOMContentLoaded", () => {\n            lucide.createIcons();\n            initCharts();\n            renderSampleLogs();\n        });\n\n        function initCharts() {\n            // 折线图\n            const ctx1 = document.getElementById(\'trafficChart\').getContext(\'2d\');\n            new Chart(ctx1, {\n                type: \'line\',\n                data: {\n                    labels: [\'周一\', \'周二\', \'周三\', \'周四\', \'周五\', \'周六\', \'今日\'],\n                    datasets: [{\n                        label: \'4K视频解析\',\n                        data: [120, 190, 150, 240, 290, 380, 420],\n                        borderColor: \'#6366f1\',\n                        backgroundColor: \'rgba(99, 102, 241, 0.15)\',\n                        fill: true,\n                        tension: 0.4\n                    }, {\n                        label: \'实况照片 / 图集\',\n                        data: [45, 80, 65, 110, 140, 190, 230],\n                        borderColor: \'#06b6d4\',\n                        backgroundColor: \'rgba(6, 182, 212, 0.1)\',\n                        fill: true,\n                        tension: 0.4\n                    }]\n                },\n                options: {\n                    responsive: true,\n                    maintainAspectRatio: false,\n                    plugins: { legend: { labels: { color: \'#94a3b8\' } } },\n                    scales: {\n                        x: { grid: { color: \'rgba(255,255,255,0.05)\' }, ticks: { color: \'#94a3b8\' } },\n                        y: { grid: { color: \'rgba(255,255,255,0.05)\' }, ticks: { color: \'#94a3b8\' } }\n                    }\n                }\n            });\n\n            // 环形图\n            const ctx2 = document.getElementById(\'distributionChart\').getContext(\'2d\');\n            new Chart(ctx2, {\n                type: \'doughnut\',\n                data: {\n                    labels: [\'抖音 4K 视频\', \'抖音实况图\', \'快手原画\', \'高清图集\'],\n                    datasets: [{\n                        data: [55, 22, 13, 10],\n                        backgroundColor: [\'#6366f1\', \'#06b6d4\', \'#f59e0b\', \'#ec4899\'],\n                        borderWidth: 0\n                    }]\n                },\n                options: {\n                    responsive: true,\n                    maintainAspectRatio: false,\n                    plugins: { legend: { position: \'bottom\', labels: { color: \'#94a3b8\', boxWidth: 12 } } }\n                }\n            });\n        }\n\n        function renderSampleLogs() {\n            const tbody = document.getElementById(\'logs-tbody\');\n            const now = new Date();\n            const sampleLogs = [\n                { time: "刚刚", platform: "抖音", type: "4K 视频", latency: "142ms", device: "Android (Redmi 2411)", status: "200 OK" },\n                { time: "1分钟前", platform: "抖音", type: "实况 LivePhoto", latency: "168ms", device: "Android App", status: "200 OK" },\n                { time: "3分钟前", platform: "快手", type: "原画视频", latency: "195ms", device: "Android App", status: "200 OK" },\n                { time: "6分钟前", platform: "抖音", type: "高清图集 ZIP", latency: "210ms", device: "Android (Redmi 2411)", status: "200 OK" },\n                { time: "10分钟前", platform: "抖音", type: "1080P 60帧", latency: "135ms", device: "Android App", status: "200 OK" },\n            ];\n\n            tbody.innerHTML = sampleLogs.map(log => `\n                <tr class="hover:bg-slate-800/40 transition">\n                    <td class="py-2.5 px-3 text-slate-400">${log.time}</td>\n                    <td class="py-2.5 px-3"><span class="px-2 py-0.5 rounded bg-indigo-500/20 text-indigo-300 font-bold">${log.platform}</span></td>\n                    <td class="py-2.5 px-3 text-white">${log.type}</td>\n                    <td class="py-2.5 px-3 text-emerald-400 font-semibold">${log.latency}</td>\n                    <td class="py-2.5 px-3 text-slate-300">${log.device}</td>\n                    <td class="py-2.5 px-3"><span class="px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-400 font-bold">${log.status}</span></td>\n                </tr>\n            `).join("");\n        }\n\n        async function runApiTest() {\n            const urlInput = document.getElementById(\'test-url\').value.trim();\n            const outputBox = document.getElementById(\'test-output-box\');\n            const outputJson = document.getElementById(\'test-output-json\');\n            \n            if (!urlInput) {\n                alert("请输入待测试的分享链接");\n                return;\n            }\n\n            outputBox.classList.remove(\'hidden\');\n            outputJson.innerText = "正在请求云端接口 /api/parse ...";\n\n            try {\n                const res = await fetch(\'/api/parse\', {\n                    method: \'POST\',\n                    headers: { \'Content-Type\': \'application/json\' },\n                    body: JSON.stringify({ url: urlInput })\n                });\n                const data = await res.json();\n                outputJson.innerText = JSON.stringify(data, null, 2);\n            } catch (err) {\n                outputJson.innerText = "请求失败: " + err.message;\n            }\n        }\n\n        function refreshData() {\n            document.getElementById(\'metric-latency\').innerText = Math.floor(150 + Math.random() * 50);\n            renderSampleLogs();\n            lucide.createIcons();\n        }\n    </script>\n</body>\n</html>\n'
